import{_ as f,C as c,o as e,c as v,a5 as t,E as r}from"./chunks/framework.D_J2JZBr.js";const p=JSON.parse('{"title":"上科大课程总览","description":"从 2026 级 EE 培养方案、四年选课节奏到 IC 相关课程与往届经验。","frontmatter":{"title":"上科大课程总览","description":"从 2026 级 EE 培养方案、四年选课节奏到 IC 相关课程与往届经验。"},"headers":[],"relativePath":"shanghaitech/courses/index.md","filePath":"shanghaitech/courses/index.md","lastUpdated":1795531638000}'),s={name:"shanghaitech/courses/index.md"};function h(n,a,i,o,l,E){const d=c("CourseTable");return e(),v("div",null,[a[0]||(a[0]=t('<h1 id="上科大课程总览" tabindex="-1" data-v-7f049f9c>上科大课程总览 <a class="header-anchor" href="#上科大课程总览" aria-label="Permalink to &quot;上科大课程总览&quot;" data-v-7f049f9c>​</a></h1><p data-v-7f049f9c>选课先看三层信息：<strong data-v-7f049f9c>你的年级培养方案决定毕业要求，教务系统决定实际开课与选课资格，课程大纲决定当学期内容和考核。</strong> 本页把它们与 IC 学习路线连接起来，不替代任何一层正式文件。</p><h2 id="数据来源与适用范围" tabindex="-1" data-v-7f049f9c>数据来源与适用范围 <a class="header-anchor" href="#数据来源与适用范围" aria-label="Permalink to &quot;数据来源与适用范围&quot;" data-v-7f049f9c>​</a></h2><p data-v-7f049f9c>下方课程表整理自 <strong data-v-7f049f9c>2026–2027 学年 SIST 官方开课表</strong>，聚焦 IC 及相关基础、体系结构、人工智能和 EDA 课程，并非学院全部课程。教师、学分、学期与先修信息均采用该学年数据。官方表明确说明开课存在不确定因素、更新可能不及时，<strong data-v-7f049f9c>最终以教务系统为准</strong>。</p><p data-v-7f049f9c>详细经验页主要依据维护者的 <strong data-v-7f049f9c>2026 春 / 秋版本课程笔记</strong>与公开课程主页重写。往届版本教师可能与当前开课表不同；不把旧班级的评分比例、作业题目或软件版本当作下一学年的承诺。</p><div class="warning custom-block" data-v-7f049f9c><p class="custom-block-title" data-v-7f049f9c>“必修”必须结合专业与年级理解</p><p data-v-7f049f9c>课程表中的课程类型不能独立用来判断你的毕业要求。例如 CS110 在开课数据中标为必修，但不在下列 2026 级 EE 专业必修清单中。跨专业选课、学分归类与替代关系须核对本人培养方案。</p></div><h2 id="_2026-级-ee-本科培养方案要点" tabindex="-1" data-v-7f049f9c>2026 级 EE 本科培养方案要点 <a class="header-anchor" href="#_2026-级-ee-本科培养方案要点" aria-label="Permalink to &quot;2026 级 EE 本科培养方案要点&quot;" data-v-7f049f9c>​</a></h2><h3 id="至少-143-学分怎样组成" tabindex="-1" data-v-7f049f9c>至少 143 学分怎样组成 <a class="header-anchor" href="#至少-143-学分怎样组成" aria-label="Permalink to &quot;至少 143 学分怎样组成&quot;" data-v-7f049f9c>​</a></h3><table tabindex="0" data-v-7f049f9c><thead data-v-7f049f9c><tr data-v-7f049f9c><th data-v-7f049f9c>类别</th><th data-v-7f049f9c>必修</th><th data-v-7f049f9c>选修</th><th data-v-7f049f9c>小计</th></tr></thead><tbody data-v-7f049f9c><tr data-v-7f049f9c><td data-v-7f049f9c>人文社科通识</td><td data-v-7f049f9c>31</td><td data-v-7f049f9c>22</td><td data-v-7f049f9c>53</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>自然科学通识</td><td data-v-7f049f9c>28</td><td data-v-7f049f9c>2</td><td data-v-7f049f9c>30</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>专业课程</td><td data-v-7f049f9c>32</td><td data-v-7f049f9c>19</td><td data-v-7f049f9c>51</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>任选课程</td><td data-v-7f049f9c>—</td><td data-v-7f049f9c>—</td><td data-v-7f049f9c>9</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c><strong data-v-7f049f9c>总计</strong></td><td data-v-7f049f9c></td><td data-v-7f049f9c></td><td data-v-7f049f9c><strong data-v-7f049f9c>143</strong></td></tr></tbody></table><p data-v-7f049f9c>SI100B 归入自然科学通识的信息课程群，不在专业课程的 32 学分中重复计算。英语、体育、课程群与实践要求也要逐项核对，不能只用总学分相加判断毕业资格。</p><h3 id="专业必修与建议学期" tabindex="-1" data-v-7f049f9c>专业必修与建议学期 <a class="header-anchor" href="#专业必修与建议学期" aria-label="Permalink to &quot;专业必修与建议学期&quot;" data-v-7f049f9c>​</a></h3><p data-v-7f049f9c>以下学期按培养方案中专业课程表整理；“二（1）”表示大二第一学期，不表示所有班级只能在该学期开设。</p><table tabindex="0" data-v-7f049f9c><thead data-v-7f049f9c><tr data-v-7f049f9c><th data-v-7f049f9c>代码</th><th data-v-7f049f9c>课程</th><th data-v-7f049f9c>学分</th><th data-v-7f049f9c>建议修读学期</th><th data-v-7f049f9c>推免前必修</th></tr></thead><tbody data-v-7f049f9c><tr data-v-7f049f9c><td data-v-7f049f9c>CS100</td><td data-v-7f049f9c>计算机编程</td><td data-v-7f049f9c>4</td><td data-v-7f049f9c>二（2）</td><td data-v-7f049f9c>是</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>EE111</td><td data-v-7f049f9c>电路基础</td><td data-v-7f049f9c>4</td><td data-v-7f049f9c>一（2）</td><td data-v-7f049f9c>是</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>EE111L</td><td data-v-7f049f9c>电路基础实验</td><td data-v-7f049f9c>1</td><td data-v-7f049f9c>一（2）</td><td data-v-7f049f9c>是</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>EE130</td><td data-v-7f049f9c>电磁学</td><td data-v-7f049f9c>4</td><td data-v-7f049f9c>二（2）/ 三（1）</td><td data-v-7f049f9c>是</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>EE130P</td><td data-v-7f049f9c>电磁学课程设计</td><td data-v-7f049f9c>2</td><td data-v-7f049f9c>二（2）/ 三（1）</td><td data-v-7f049f9c>是</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>EE150</td><td data-v-7f049f9c>信号与系统</td><td data-v-7f049f9c>4</td><td data-v-7f049f9c>二（1）/ 二（2）</td><td data-v-7f049f9c>是</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>EE150L</td><td data-v-7f049f9c>信号与系统实验</td><td data-v-7f049f9c>1</td><td data-v-7f049f9c>二（1）/ 二（2）</td><td data-v-7f049f9c>是</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>EE115A</td><td data-v-7f049f9c>模拟电路</td><td data-v-7f049f9c>3</td><td data-v-7f049f9c>二（1）/ 二（2）</td><td data-v-7f049f9c>是</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>EE115B</td><td data-v-7f049f9c>数字电路</td><td data-v-7f049f9c>3</td><td data-v-7f049f9c>二（1）/ 二（2）</td><td data-v-7f049f9c>是</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>SI99</td><td data-v-7f049f9c>毕业论文</td><td data-v-7f049f9c>6</td><td data-v-7f049f9c>四（1+2）</td><td data-v-7f049f9c>否</td></tr></tbody></table><h3 id="专业限选-三选二" tabindex="-1" data-v-7f049f9c>专业限选：三选二 <a class="header-anchor" href="#专业限选-三选二" aria-label="Permalink to &quot;专业限选：三选二&quot;" data-v-7f049f9c>​</a></h3><p data-v-7f049f9c>本学科选修共 <strong data-v-7f049f9c>19 学分</strong>，其中专业限选至少 <strong data-v-7f049f9c>8 学分</strong>：<strong data-v-7f049f9c>EE140 通信原理、EE120 半导体器件基础、EE160 控制原理</strong>三门各 4 学分，至少选两门，方案建议在三（1）/ 三（2）修读；多选的学分计入本学科选修的 19 学分，不是额外再加一套限选额度。该限选要求标为推免前必修。</p><p data-v-7f049f9c>选择可结合方向：器件与 IC 设计关注半导体基础，信号链与无线系统关注通信，反馈系统与电力电子关注控制。方向兴趣不免除培养方案要求。</p><h3 id="推免前不只检查专业课" tabindex="-1" data-v-7f049f9c>推免前不只检查专业课 <a class="header-anchor" href="#推免前不只检查专业课" aria-label="Permalink to &quot;推免前不只检查专业课&quot;" data-v-7f049f9c>​</a></h3><p data-v-7f049f9c>方案还将相关数学、物理及实验、SI100B、化学 / 生物课程群指定选课，以及多项思政和通识必修标为推免前必修。建议大三前按教务系统逐项核对；“已选但未结课”与“已满足要求”不是一回事。推免资格和具体审核时间另见学校当年通知及<a href="/shanghaitech-ic-wiki-dev.github.io/career/graduate-study/baoyan" data-v-7f049f9c>推免准备</a>。</p><h2 id="典型四年选课节奏" tabindex="-1" data-v-7f049f9c>典型四年选课节奏 <a class="header-anchor" href="#典型四年选课节奏" aria-label="Permalink to &quot;典型四年选课节奏&quot;" data-v-7f049f9c>​</a></h2><p data-v-7f049f9c>培养方案提供两张课程分布图，主要差别是模拟 / 数字电路与信号与系统的先后，以及电磁学、部分通识的安排。下表保留两条可选节奏，不把分布图中有排版差异的每学期小计当作固定负荷。</p><table tabindex="0" data-v-7f049f9c><thead data-v-7f049f9c><tr data-v-7f049f9c><th data-v-7f049f9c>学期</th><th data-v-7f049f9c>分布图路径 A</th><th data-v-7f049f9c>分布图路径 B / 安排重点</th></tr></thead><tbody data-v-7f049f9c><tr data-v-7f049f9c><td data-v-7f049f9c>大一秋</td><td data-v-7f049f9c>线性代数、数分 I / 高数 I、SI100B，配合军事、英语、体育与通识</td><td data-v-7f049f9c>核心专业基础相同；先建立数学与数字系统直觉</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>大一春</td><td data-v-7f049f9c>数分 II / 高数 II、普通物理 I 及实验、EE111 + EE111L</td><td data-v-7f049f9c>路径 B 同期还安排经济学导论；关注实验与理论配合</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>大一暑期</td><td data-v-7f049f9c>暑学期课程；暑假安排国家安全教育、社会实践</td><td data-v-7f049f9c>按当年具体组织方式参加</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>大二秋</td><td data-v-7f049f9c>EE150 + EE150L、概率统计、普通物理 II 及实验、化学 / 生物选课</td><td data-v-7f049f9c>路径 B 改为 EE115A + EE115B，信号课程后移</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>大二春</td><td data-v-7f049f9c>EE115A + EE115B、CS100，以及人文写作等</td><td data-v-7f049f9c>路径 B 安排 EE150 + EE150L、CS100、EE130 + EE130P</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>大二暑期</td><td data-v-7f049f9c>暑学期课程；暑假安排产业实践</td><td data-v-7f049f9c>若参加芯片实训，提前准备 Linux 与电路基础</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>大三秋</td><td data-v-7f049f9c>限选三选二、EE130 + EE130P、专业选修</td><td data-v-7f049f9c>路径 B 已完成电磁学，可分配给专业选修；核对推免前必修</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>大三春</td><td data-v-7f049f9c>专业选修，配合思政与体育</td><td data-v-7f049f9c>围绕方向补课，避免多个大型项目同时从零启动</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>大三暑期</td><td data-v-7f049f9c>暑学期课程</td><td data-v-7f049f9c>按实际安排连接科研、实践与毕业课题准备</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>大四秋</td><td data-v-7f049f9c>SI99 毕业论文启动 / 推进、体育健康相关要求</td><td data-v-7f049f9c>核查所有课程群、学分类别与毕业缺口</td></tr><tr data-v-7f049f9c><td data-v-7f049f9c>大四春</td><td data-v-7f049f9c>持续完成毕业论文及毕业要求</td><td data-v-7f049f9c>不能把所有欠修与毕业设计集中到最后几周</td></tr></tbody></table><p data-v-7f049f9c>这是培养方案的阅读辅助，不是自动生成的个人课表。更多先后修关系可参考<a href="/shanghaitech-ic-wiki-dev.github.io/learning/digital-ic/" data-v-7f049f9c>数字路线</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/learning/analog-ic/" data-v-7f049f9c>模拟路线</a>与<a href="/shanghaitech-ic-wiki-dev.github.io/learning/devices-and-process/" data-v-7f049f9c>器件路线</a>。</p><h2 id="研究生课程与本研共享" tabindex="-1" data-v-7f049f9c>研究生课程与本研共享 <a class="header-anchor" href="#研究生课程与本研共享" aria-label="Permalink to &quot;研究生课程与本研共享&quot;" data-v-7f049f9c>​</a></h2><p data-v-7f049f9c>学院提供本硕博课程体系与课程图谱，因此本页也收录 EE219、EE291F、CS290U、EE213、EE215A 等研究生课程，帮助本科生规划进阶。这里的“本研共享”指<strong data-v-7f049f9c>把课程放进连续的学习网络中查看和规划</strong>，不意味着所有研究生课对本科生无条件开放，也不意味着自动计入本科专业选修或研究生培养学分。</p><p data-v-7f049f9c>选课前确认：是否允许本年级修读、先修是否满足、是否需要教师同意、学分如何认定、实验资源是否覆盖本科生。尤其注意实验与课程设计可能独立设课、独立考核；页面合并介绍不等于选课时合并注册。</p><h2 id="ic-相关课程表" tabindex="-1" data-v-7f049f9c>IC 相关课程表 <a class="header-anchor" href="#ic-相关课程表" aria-label="Permalink to &quot;IC 相关课程表&quot;" data-v-7f049f9c>​</a></h2>',26)),r(d,{filter:""}),a[1]||(a[1]=t('<h2 id="有详细经验页的课程" tabindex="-1" data-v-7f049f9c>有详细经验页的课程 <a class="header-anchor" href="#有详细经验页的课程" aria-label="Permalink to &quot;有详细经验页的课程&quot;" data-v-7f049f9c>​</a></h2><div class="course-experience-grid" data-v-7f049f9c><a href="/shanghaitech/courses/si100b" data-v-7f049f9c><strong data-v-7f049f9c>SI100B 信息科学技术导论</strong><span data-v-7f049f9c>从 Logisim、算术电路到 miniCPU 的硬件入口。</span></a><a href="/shanghaitech/courses/ee115a" data-v-7f049f9c><strong data-v-7f049f9c>EE115A 模拟电路</strong><span data-v-7f049f9c>器件、小信号、差分放大与负反馈。</span></a><a href="/shanghaitech/courses/ee115b" data-v-7f049f9c><strong data-v-7f049f9c>EE115B 数字电路</strong><span data-v-7f049f9c>组合与时序逻辑、HDL、状态机项目。</span></a><a href="/shanghaitech/courses/ee150" data-v-7f049f9c><strong data-v-7f049f9c>EE150 / EE150L 信号与系统</strong><span data-v-7f049f9c>卷积、频域、变换与实验学习方法。</span></a><a href="/shanghaitech/courses/cs110" data-v-7f049f9c><strong data-v-7f049f9c>CS110 / CS110P 体系结构</strong><span data-v-7f049f9c>从 C 和 RISC-V 到流水线、存储与并行。</span></a><a href="/shanghaitech/courses/ee113" data-v-7f049f9c><strong data-v-7f049f9c>EE113 / EE113L 数字集成电路 I</strong><span data-v-7f049f9c>从 CMOS 到全定制版图与寄生后仿。</span></a><a href="/shanghaitech/courses/ee291f" data-v-7f049f9c><strong data-v-7f049f9c>EE291F 数字 VLSI 设计流程</strong><span data-v-7f049f9c>Linux、工程管理、综合与形式等价。</span></a><a href="/shanghaitech/courses/ee219" data-v-7f049f9c><strong data-v-7f049f9c>EE219 智能计算系统</strong><span data-v-7f049f9c>量化、脉动阵列、Gemmini 与软硬件映射。</span></a><a href="/shanghaitech/courses/cs290u" data-v-7f049f9c><strong data-v-7f049f9c>CS290U 深度学习工程实践</strong><span data-v-7f049f9c>真实数据、评估归因与项目交付。</span></a><a href="/shanghaitech/courses/cadence-summer" data-v-7f049f9c><strong data-v-7f049f9c>Cadence 集成电路暑期实训</strong><span data-v-7f049f9c>数字后端 RTL-to-GDS 与签核实践。</span></a></div><div class="info custom-block" data-v-7f049f9c><p class="custom-block-title" data-v-7f049f9c>征集</p><p data-v-7f049f9c>欢迎补充不同年级、不同班级的经验，并注明学期、课程代码与可公开核验的资料来源。不要上传答案包、账号或受限工艺文件。提交方式见<a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing" data-v-7f049f9c>参与共建</a>。</p></div><h2 id="参考与来源" tabindex="-1" data-v-7f049f9c>参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;" data-v-7f049f9c>​</a></h2><ul data-v-7f049f9c><li data-v-7f049f9c><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer" data-v-7f049f9c>SIST 2026–2027 学年课程设置</a>。</li><li data-v-7f049f9c><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Undergraduate/Degree%20Programmes/2026%20Bachelor%20Degree%20Prorgams%20in%20EE.htm" target="_blank" rel="noreferrer" data-v-7f049f9c>2026 级电子信息工程本科培养方案</a>：学分构成、专业课程表、限选与课程分布图。</li><li data-v-7f049f9c><a href="https://sist.shanghaitech.edu.cn/2835/list.htm" target="_blank" rel="noreferrer" data-v-7f049f9c>信息学院本硕博课程体系</a>、<a href="https://sist.shanghaitech.edu.cn/2833/list.htm" target="_blank" rel="noreferrer" data-v-7f049f9c>本科生培养入口</a>。</li><li data-v-7f049f9c>各详情页所列公开课程主页，以及维护者 2026 春 / 秋 / 夏课程笔记整理；经验材料不替代官方规则。</li></ul>',5))])}const u=f(s,[["render",h],["__scopeId","data-v-7f049f9c"]]);export{p as __pageData,u as default};
